SELECT CASE WHEN p.stock_qty >= 382 THEN 'high' WHEN p.stock_qty >= 166 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, CASE WHEN p.brand IN ('Globex', 'Umbrella') THEN 'core' ELSE 'other' END AS brand_group, COUNT(*) AS num_inventory, AVG(i.quantity) AS avg_quantity FROM inventory i JOIN stores s ON s.id = i.store_id JOIN products p ON i.product_id = p.id GROUP BY CASE WHEN p.stock_qty >= 382 THEN 'high' WHEN p.stock_qty >= 166 THEN 'mid' ELSE 'low' END, CASE WHEN p.brand IN ('Globex', 'Umbrella') THEN 'core' ELSE 'other' END ORDER BY avg_quantity, num_inventory DESC, stock_qty_bucket, brand_group LIMIT 3
